								                        "reserved" -> slotObj.setSlotStatus(SlotStatus.RESERVED)
								                        "occupied" -> slotObj.setSlotStatus(SlotStatus.OCCUPIED)
								                    }
								CommUtils.outcyan("$name | Slot $sId aggiornato a stato: $sState")
								answer("setSlot", "setSlotChanged", "setSlotChanged(NOARGS)"   )  
